nsresult DispatchSyncRunnable(SyncRunnableBase* r) {
  if (NS_IsMainThread()) {
    r->Run();
  } else {
    mozilla::MonitorAutoLock lock(r->Monitor());
    nsresult rv = NS_DispatchToMainThread(r);
    if (NS_FAILED(rv)) return rv;
    while (!r->IsCompleted()) {
      lock.Wait();
    }
  }
  return r->Result();
}
